/** `public/docs-content/api-reference.json` — generated by the engine's ApiReferenceDocumentTests from its OpenAPI document. */
export interface ApiReferenceParameter {
  name: string;
  in: 'path' | 'query' | 'header' | string;
  required: boolean;
  type?: string;
}

export interface ApiReferenceEndpoint {
  method: string;
  path: string;
  summary?: string;
  /** `permission`, `anonymous` or `session`. */
  access: 'permission' | 'anonymous' | 'session' | string;
  permission?: string;
  rateLimit?: string;
  parameters: ApiReferenceParameter[];
  body?: string;
  response?: string;
}

export interface ApiReferenceGroup {
  name: string;
  endpoints: ApiReferenceEndpoint[];
}

export interface ApiReference {
  title: string;
  version: string;
  source: string;
  basePath: string;
  endpointCount: number;
  groups: ApiReferenceGroup[];
}
